// Security validation and signature verification
const crypto = require('crypto');
const items = $input.all();

if (!items.length) {
  throw new Error('No webhook data received');
}

const payload = items[0];
const headers = payload.headers || {};

// Verify required headers
const requiredHeaders = ['x-hub-signature-256', 'x-github-delivery', 'user-agent'];
for (const header of requiredHeaders) {
  if (!headers[header]) {
    throw new Error(`Missing required header: ${header}`);
  }
}

// Verify User-Agent
if (!headers['user-agent'].includes('GitHub-Actions-Secure-Webhook')) {
  throw new Error('Invalid User-Agent');
}

// Get webhook secret from environment
const webhookSecret = process.env.WEBHOOK_SECRET;
if (!webhookSecret) {
  throw new Error('Webhook secret not configured');
}

// Verify signature
const bodyString = JSON.stringify(payload.body);
const expectedSignature = crypto
  .createHmac('sha256', webhookSecret)
  .update(bodyString)
  .digest('base64');

const receivedSignature = headers['x-hub-signature-256'].replace('sha256=', '');

if (!crypto.timingSafeEqual(Buffer.from(expectedSignature), Buffer.from(receivedSignature))) {
  throw new Error('Invalid webhook signature');
}

// Rate limiting check (simple in-memory)
const now = Date.now();
const rateLimitWindow = 60000; // 1 minute
const maxRequests = 10;
const clientKey = headers['x-github-delivery'] || 'unknown';

// This would ideally use Redis or similar for production
if (!global.rateLimitData) {
  global.rateLimitData = {};
}

if (!global.rateLimitData[clientKey]) {
  global.rateLimitData[clientKey] = [];
}

// Clean old requests
global.rateLimitData[clientKey] = global.rateLimitData[clientKey].filter(
  timestamp => now - timestamp < rateLimitWindow
);

// Check rate limit
if (global.rateLimitData[clientKey].length >= maxRequests) {
  throw new Error('Rate limit exceeded');
}

// Add current request
global.rateLimitData[clientKey].push(now);

return [{
  json: {
    validation: 'passed',
    timestamp: new Date().toISOString(),
    github_delivery: headers['x-github-delivery'],
    verified: true
  }
}];

// Input sanitization and validation
const inputData = $input.first().json;
const originalPayload = $('Secure GitHub Webhook').first().json.body;

// Sanitization functions
function sanitizeString(str, maxLength = 1000) {
  if (typeof str !== 'string') return '';
  return str
    .replace(/[<>"'&]/g, '') // Remove potentially dangerous characters
    .substring(0, maxLength)
    .trim();
}

function sanitizeNumber(num) {
  const parsed = parseInt(num, 10);
  return isNaN(parsed) ? 0 : Math.abs(parsed);
}

function sanitizeUrl(url) {
  try {
    const parsed = new URL(url);
    if (!['https:', 'http:'].includes(parsed.protocol)) {
      throw new Error('Invalid protocol');
    }
    if (!parsed.hostname.includes('github.com')) {
      throw new Error('Invalid hostname');
    }
    return parsed.toString();
  } catch {
    return null;
  }
}

// Validate required fields
if (!originalPayload.event || !originalPayload.repository) {
  throw new Error('Missing required fields');
}

// Sanitize and validate all inputs
const sanitizedData = {
  event: sanitizeString(originalPayload.event, 50),
  repository: sanitizeString(originalPayload.repository, 100),
  pr_number: sanitizeNumber(originalPayload.pr_number),
  pr_url: sanitizeUrl(originalPayload.pr_url),
  diff_url: sanitizeUrl(originalPayload.diff_url),
  author: sanitizeString(originalPayload.author, 50),
  timestamp: originalPayload.timestamp,
  github_delivery: sanitizeString(originalPayload.github_delivery, 100)
};

// Validate sanitized data
if (!sanitizedData.pr_url || !sanitizedData.diff_url) {
  throw new Error('Invalid URLs provided');
}

if (sanitizedData.pr_number <= 0) {
  throw new Error('Invalid PR number');
}

// Security logging
console.log(`[SECURITY] Webhook processed: PR #${sanitizedData.pr_number} from ${sanitizedData.author}`);

return [{
  json: sanitizedData
}];

// Secure Claude prompt preparation with content filtering
const prData = $input.first().json;
const diffResponse = $('Secure Diff Fetch').first();

// Security check for diff response
if (!diffResponse || diffResponse.statusCode !== 200) {
  throw new Error('Failed to fetch diff or invalid response');
}

let diffContent = '';
if (diffResponse.body) {
  diffContent = typeof diffResponse.body === 'string' 
    ? diffResponse.body 
    : String(diffResponse.body);
}

// Content filtering and size limits
const MAX_DIFF_SIZE = 50000; // 50KB limit
const MAX_LINES = 1000;

if (diffContent.length > MAX_DIFF_SIZE) {
  diffContent = diffContent.substring(0, MAX_DIFF_SIZE) + '\n[TRUNCATED - Content too large]';
}

// Filter potentially sensitive content
const sensitivePatterns = [
  /(?:password|passwd|pwd)\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
  /(?:api[_-]?key|apikey)\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
  /(?:secret|token)\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi,
  /(?:private[_-]?key)\s*[=:]\s*['"]?([^'"\s]+)['"]?/gi
];

for (const pattern of sensitivePatterns) {
  diffContent = diffContent.replace(pattern, (match, capture) => {
    const replacement = '*'.repeat(Math.min(capture.length, 8));
    return match.replace(capture, `[REDACTED-${replacement}]`);
  });
}

// Limit number of lines
const lines = diffContent.split('\n');
if (lines.length > MAX_LINES) {
  diffContent = lines.slice(0, MAX_LINES).join('\n') + '\n[TRUNCATED - Too many lines]';
}

// Prepare secure prompt
const securePrompt = `You are a secure code review assistant. Analyze this pull request with focus on:

**Repository:** ${prData.repository}
**PR Number:** ${prData.pr_number}
**Author:** ${prData.author}
**Analysis Timestamp:** ${new Date().toISOString()}

**Code Changes:**
\`\`\`diff
${diffContent}
\`\`\`

**Review Guidelines:**
1. Focus on code quality, security, and best practices
2. Do not include sensitive information in your response
3. Provide constructive feedback only
4. Keep responses professional and helpful
5. Flag any potential security vulnerabilities

**Required Analysis:**
- Code quality assessment
- Security considerations
- Performance implications
- Best practice adherence
- Improvement suggestions

**Response Format:**
Provide a structured review with clear sections and actionable feedback.`;

// Validate prompt size
if (securePrompt.length > 100000) {
  throw new Error('Prompt too large for processing');
}

return [{
  json: {
    ...prData,
    claude_prompt: securePrompt,
    diff_size: diffContent.length,
    diff_lines: diffContent.split('\n').length,
    security_filtered: true
  }
}];

// Output sanitization and security filtering
const analysisResult = $input.first().json;
const prData = $('Secure Prompt Preparation').first().json;

if (!analysisResult.content) {
  throw new Error('No analysis content received');
}

let reviewContent = analysisResult.content;

// Security filtering for output
const outputFilters = [
  // Remove any potential code injection
  /<script[^>]*>[\s\S]*?<\/script>/gi,
  /<iframe[^>]*>[\s\S]*?<\/iframe>/gi,
  /javascript:/gi,
  /data:text\/html/gi,
  // Remove potential markdown injection
  /!\[.*?\]\((?!https:\/\/github\.com)[^\)]*\)/gi
];

for (const filter of outputFilters) {
  reviewContent = reviewContent.replace(filter, '[FILTERED_CONTENT]');
}

// Ensure content length limits
const MAX_COMMENT_LENGTH = 65000; // GitHub comment limit
if (reviewContent.length > MAX_COMMENT_LENGTH) {
  reviewContent = reviewContent.substring(0, MAX_COMMENT_LENGTH - 100) + 
    '\n\n[Review truncated due to length limits]';
}

// Add security footer
const securityFooter = `\n\n---\n🛡️ **Security Notice:** This review was generated by a secure AI system with content filtering and validation.\n🔍 **Analysis ID:** ${prData.github_delivery}\n⏰ **Generated:** ${new Date().toISOString()}`;

const finalContent = `🤖 **Secure Claude Code Assistant Review**\n\n${reviewContent}${securityFooter}`;

// Log security event
console.log(`[SECURITY] Review generated for PR #${prData.pr_number}, Content length: ${finalContent.length}`);

return [{
  json: {
    ...prData,
    filtered_content: finalContent,
    content_length: finalContent.length,
    security_validated: true
  }
}];

// Security logging and monitoring
const result = $input.first().json;
const prData = $('Output Sanitizer').first().json;

// Log successful completion
const logEntry = {
  timestamp: new Date().toISOString(),
  event: 'secure_review_completed',
  pr_number: prData.pr_number,
  repository: prData.repository,
  author: prData.author,
  github_delivery: prData.github_delivery,
  content_length: prData.content_length,
  diff_size: prData.diff_size,
  security_validated: true,
  status: 'success'
};

console.log(`[AUDIT] ${JSON.stringify(logEntry)}`);

return [{
  json: {
    status: 'success',
    message: 'Secure code analysis completed successfully',
    pr_number: prData.pr_number,
    analysis_id: prData.github_delivery,
    timestamp: new Date().toISOString(),
    security_level: 'high'
  }
}];
